"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _label(gap: Span) -> str:
    start, end = _clock(gap.start), _clock(gap.end)
    return f"gap {start}-{end} ({gap.minutes} min)"


def _check_inside(worked: Iterable[Span], hours: Span):
    for span in worked:
        if span.start < hours.start or span.end > hours.end:
            raise ValueError(f"outside hours: {span}")


def _free_stretches(merged: List[Span], hours: Span):
    lefts = [hours.start] + [span.end for span in merged]
    rights = [span.start for span in merged] + [hours.end]
    pairs = zip(lefts, rights)
    return [
        Span(*pair) for pair in pairs if pair[0] < pair[1]
    ]


# ---
def uncovered_gaps(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    worked = list(worked)
    _check_inside(worked, hours)
    merged = merge_spans(worked)
    stretches = _free_stretches(merged, hours)
    return [_label(gap) for gap in stretches]

