import unittest

from hourglass.models import Span
from hourglass.gaps import uncovered_gaps

HOURS = Span(8 * 60, 17 * 60)


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(480, 720), Span(780, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, HOURS),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = [Span(540, 700), Span(600, 720)]
        self.assertEqual(
            uncovered_gaps(worked, HOURS),
            [
                "gap 08:00-09:00 (60 min)",
                "gap 12:00-17:00 (300 min)"
            ]
        )

    def test_nothing_worked(self):
        self.assertEqual(
            uncovered_gaps([], HOURS),
            ["gap 08:00-17:00 (540 min)"]
        )

    def test_full_coverage(self):
        self.assertEqual(uncovered_gaps([HOURS], HOURS), [])

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([Span(420, 600)], HOURS)
